/* Hasibat Al-Lira — offline, deterministic PNG sharing.
 * All values come from the same calculation state shown on screen.
 * This feature does not query an additional rate source or alter a rate. */
(function () {
  'use strict';
  const shareButton = document.getElementById('shareResults');
  const status = document.getElementById('shareResultsStatus');
  if (!shareButton || !status) return;
  const codes = {new:'SYP NEW',old:'SYP OLD',try:'TRY',usd:'USD',eur:'EUR'};
  const coreRows = ['new','old','usd','try','eur'];

  // Exactly 53 owner-provided awareness messages. No server access, no replacements.
  const AWARENESS_MESSAGES = Object.freeze(["الإسلام ليس متعبًا؛ الذي يتعب هو المسلم حين يبتعد عن مصدر قوته، ويترك عقله لغيره، ووقته لمنصته، وتربية أبنائه للصدفة.","لا ينتصر الحق بمجرد كونه حقًا إذا عجز أهله عن شرحه وتمثيله؛ لأنه لا يحتاج إلى الكذب، بل يحتاج إلى حضور مستمر، وصوت واضح، وقدوة صادقة.","الذي يُضعف المسلم ليس كثرة الشبهات، بل البعد عن مصدر قوته. فإذا عاد إلى كتاب ربه وسنة نبيه، وعرف ربه، وأتقن علوم عصره، نهض عزيزًا ثابتًا.","مهما كان عمري، فأنا في حضرته صغير. ومهما علا قدري، فأنا ثمرة من ثمار خبرته. ومهما ظننت أنني أسرع منه، فأبي يعرف الطريق أكثر مني.","استعادة التاريخ ليست بكاءً على الماضي، بل بداية لاستعادة المستقبل؛ فالأمة التي أنجبت الخوارزمي وابن الهيثم قادرة أن تنجب من جديد.","الدفاع عن فضل علماء المسلمين لا يعني إنكار إنجازات غيرهم؛ فالإنصاف أن يُذكر السابق، والشارح، والمؤسس، والمطور، كلٌّ بقدره.","كان المسلمون أصحاب حضارة كبرى؛ مدنهم مقصد للعلم، ولغتهم لغة المعرفة، وكتب علمائهم تُدرّس خارج بلادهم.","حذف الحضارة الإسلامية من تاريخ العلم ليس حذف فصل عابر، بل نزع حلقة مركزية من السلسلة التي صنعت العالم الحديث.","التجهيل الممنهج لا يعني منع كل مدرسة، بل يعني تقديم معرفة محدودة تخدم الحاكم، وتُضعف قدرة الأمة على إنتاج نخبة مستقلة وواعية.","الخلل ليس في الاعتراف بفضل علماء أوروبا، بل في احتكار تعريف الاكتشاف، فتُهمّش المقدمات الإسلامية، وتُقدّم النهايات الأوروبية كأنها البداية كلها.","استعادة تاريخ علماء المسلمين ليست حنينًا للماضي، بل بداية لاستعادة الثقة وبناء المستقبل؛ فالأمة التي قدّمت العلم تستطيع أن تُضيف إليه من جديد.","حين يكتب المنتصر التاريخ وحده، تتحول حضارة قدمت العلم قرونًا إلى هامش صغير، وتبدو أوروبا كأنها بداية القصة ونهايتها.","الاقتصاد الاستعماري لم يكن ليبقى بالشعوب، بل بالخدم وأسواق المستعمر؛ لذلك أضعفت الصناعات المحلية، واستُنزفت الموارد، وهيئت الأمة منشغلة بالحاجة.","حين تُهمّش لغة الأمة في التعليم والإدارة، لا تُضعف الكلمات فقط؛ بل تُضرب الذاكرة والهوية، ويُفصل الجيل عن تراثه ومصادر قوته.","الإنصاف في تاريخ العلم يقتضي ألا نختزل السلسلة كلها في آخر اسم وصل إلى الصيغة النهائية. فمن مهّد للفكرة وشرحها وقاسها جزء من القصة لا هامش فيها.","ضرب اللغة ليس أمرًا ثقافيًا ثانويًا؛ إنه ضرب للذاكرة والهوية والمعرفة. فإذا هُمّشت لغة الأمة، انقطع كثير من أبنائها عن تراثهم ومصادر قوتهم.","لسنا ضد الغرب، ولا ننكر فضل علمائه، لكننا نرفض أن يُمحى السابق لتعظيم اللاحق. العدل أن نذكر من لاحظ، ومن فسّر، ومن قاس، ومن طوّر.","في الكيمياء، أسهم جابر بن حيان والمدرسة الجابرية والرازي في تأسيس التجريب المبكر وتقنيات المختبر، من التقطير والتبلور إلى الأدوات والعمليات والتنقية، ثم جاء الأوروبيون ليدفعوا الكيمياء الحديثة على أساس كمي أكثر صرامة. البداية أقدم من الرواية الشائعة.","لم يكن نيوتن أول من عرف أن الأجسام تسقط نحو الأرض، فقد سبق علماء مثل البيروني إلى دراسة الثقل واتجاه الأجسام نحو مركز الأرض، لكن نيوتن جمع بين سقوط الأجسام وحركة الأجرام في قانون رياضي كوني واحد. الإنصاف يقتضي أن يُذكر السابق واللاحق معًا.","لم تكن الحضارة الإسلامية جسرًا صامتًا بين اليونان وأوروبا، بل كانت في مراحل كثيرة أهم مركز عالمي للعلوم والفلك والرياضيات والطب والبصريات والفلسفة والكيمياء والهندسة. كان العالم يأتي إلى بغداد ودمشق والقاهرة وقرطبة وصقلية ليتعلم، وكانت الترجمة ثم التأليف والتجريب أساس النهضة.","فكرة الآلة القابلة للبرمجة لم تبدأ في العصر الصناعي الحديث، فقد صمم بنو موسى أنظمة آلية مبتكرة، وابتكر الجزري آلات وتحكمًا ميكانيكيًا مؤقتًا بالماء والعمل. ثم جاء جوزيف جاكار وباباج والحاسوب الحديث. لا تمحى البدايات لأن الصورة النهائية تغيرت.","لم يكن الاستعمار سبب كل ضعف أصاب العالم الإسلامي، لكنه استغل الضعف وعمّقه. سيطر على الأرض والتعليم واللغة والاقتصاد والذاكرة، فحوّل كثيرًا من الشعوب من أمة تنتج العلم إلى مجتمعات تستهلكه وتُقسم وتُبعد عن الثقة بتاريخها.","في قصة الكاميرا، لم يخترع ابن الهيثم التصوير الحديث، لكنه وضع أهم الأسس العلمية والبصرية التي تقوم عليها الكاميرا، عبر دراسته للضوء والظلال وتكوين الصورة ومسار الضوء. ثم جاء نيبس لتثبيت الصورة، وتطورت تقنيات التصوير الضوئي.","العلم لا يولد دفعة واحدة. قد يبدأ بملاحظة، ثم تفسير، ثم قياس، ثم قانون، ثم تطبيق. لكن المناهج الحديثة كثيرًا ما تختصر هذه السلسلة كلها في آخر اسم وصل إلى الصيغة النهائية، فتختفي البدايات ويُمحى من وضع الأساس.","في الطب، قدم ابن النفيس أول وصف صحيح معروف للدورة الدموية الرئوية، فرفض فكرة الثقوب الخفية في جدار القلب وبين مسار الدم بين القلب والرئتين. ثم جاء هارفي فأثبت بالتجربة والحساب الدورة الدموية العامة في الجسم.","لم تكن قوة الحضارة الإسلامية في ادعاء أن كل العلوم بدأت منها، بل في ثقتها التي جعلتها تأخذ علم اليونان والفرس والهنود والسريان، وتحفظ أسماء أصحابها، ثم تشرحه وتنقده وتصححه وتضيف إليه. كانت الأمانة في النقل عندها جزءًا من الأمانة العلمية.","ناقش ابن الهيثم أن الضوء يحتاج إلى زمن لينتقل، ونقض البيروني أنه أسرع من الصوت، ثم جاء رومر فاستنتج زمنية انتقاله فلكيًا، وتبعه هيغنز وفيزو في الحساب والقياس. هكذا تُكتب تواريخ العلم كاملة، لا باقتطاع مراحله الأولى.","البيت الذي يمنع أبناءه من السؤال لا يحميهم، بل يترك أسئلتهم حتى يجيب عنها الغرباء. علّم ابنك أن يسأل بأدب، وأن يبحث بصدق، وأن يعود إليك من غير خوف.","الحضارة ليست مباني مرتفعة وتقنيات متقدمة فقط؛ بل إنسان يعرف واجبه، ومؤسسة تحفظ الحقوق، وعلم يتحول إلى عمل، وأخلاق تمنع القوة من أن تصبح ظلمًا.","من يملك انتباهك، يستطيع أن يختار لك ما تفكر فيه، حتى إن لم يستطع أن يفرض عليك ما تعتقده. لذلك أصبح حفظ الوقت والانتباه جزءًا من حماية العقل والهوية.","ليست كل فكرة شائعة صحيحة، فقد يصنع التكرار شعورًا زائفًا بأن الرأي المنتشر حقيقة محسومة. فالعاقل لا يقيس صدق الكلام بعدد من يرددونه، بل بقوة دليله وسلامة مصدره.","لا نريد مسلمًا تابعًا لكل صوت، بل صاحب بصيرة يعرف من أين يأخذ، وعلى أي أصل يبني.","لا يكفي أن يعرف المسلم أن دينه حق فحسب، بل يجب أن يفهم لماذا هو حق، وكيف يثبته ويدافع عنه.","من فهم دينه على بصيرة، لم تضره كثرة الأصوات، ولم تخدعه زينة الباطل.","ليست قوة المسلم في كثرة الجدل، بل في صحة الحجة، وعدل النظر، وحسن البيان.","يبدأ الإصلاح من الفرد، ثم الأسرة، ثم الوعي العام. فإذا صلح التصور، وصح العلم، وقوي الخلق، صار المسلم جزءًا من الحل، لا رقمًا جديدًا في قائمة المتعبين.","من المفارقات العجيبة أن بعض الخطابات الغربية تقدم شيخ الإسلام ابن تيمية بوصفه مرجعًا للتطرف، حتى إن دراسة منشورة على موقع الحكومة البريطانية وصفت فئة من أبرز المراجع الفكرية التي يستند إليها التيار السني المتشدد.","السؤال: ما قولكم فيمن جعل مرجعه كتاب الله وسنة نبيه ﷺ الصحيحة، وفهمهما على ما ثبت عن الصحابة والتابعين لهم بإحسان، ولم يقدم قول أحد ولا تعصبًا على الدليل، ورأى اجتهادات العلماء أقوالًا بشرية تُقبل بقدر موافقتها للدليل، وتُرد بقدر مخالفتها له، مع حفظ مكانة العلماء وعدم تقديسهم؟\nالجواب: هذا هو منهج السلف الصالح.","لو كان لا ينكر المنكر إلا من لم يقع فيه، لما أنكر المنكر إلا محمد صلى الله عليه وسلم.\nفمن منا معصوم؟\nوفي الحديث القدسي: إنكم تخطئون بالليل والنهار.","هجرُ العاصي بدلَ إصلاحه لا يفتح له باب التوبة، بل قد يورثه احتقارًا، ويُغلق في وجهه طريق العودة.\n\nوليس كل عاصٍ يُهجر؛ فمن كان يكره ذنبه، ويقبل النصح، فحقّه الصحبة الصالحة والتذكير.\n\nوأما من يجاهر بالمعصية، ويُزيّنها، ويدعو إليها، فذلك الذي تُحذر صحبته.","ليس كل عاصٍ رفيق سوء؛ فقد يذنب المرء وهو يكره ذنبه، وينتظر يدًا تأخذ به إلى التوبة. وإنما رفيق السوء حقًا هو من يهون عليك المعصية، ويزينها لك، ويبعدك عن الله. فالصاحب يُقاس بالأثر: هل ترتقي معه، أم تسقط به؟","غلب على تعليم أجيال سابقة أن يكون الاهتمام بالحفظ أكثر من الفهم والعمل.\n\nوالحفظ بلا فهم يضعف مع الأيام، أما الفهم فيثبت، ويصنع وعيًا وسلوكًا، ويبقى أثره في الناس.\n\nلذلك واجبنا أن نبني جيلًا لا يردد ما يحفظه فقط، بل يفهمه، ويعمل به، وينفع به غيره.","إذا تكررت الصورة المشوهة، فلا يكفي أن ننفيها مرة واحدة. يجب أن تتكرر الحقيقة كذلك.","ما الذي يُستهدف في الشاب؟ وقته، وانتباهه، وصورته عن نفسه، ومرجعيته، وطموحه.","الحلال والحرام لا تصنعهما الدعاية، والعدل لا تحدده الدولة الأقوى.","المسلم المستيقظ لا يصدق كل شائعة، ولا يحول كل خطأ إلى خطة عالمية، ولا يبرئ نفسه من مسؤولية التقصير.","النسوية الغربية لم تستطع تحصيل حقوق المرأة التي حصلت عليها المرأة المسلمة منذ 1400 عام.","نريد مسلمًا يصحو، ثم يفهم، ثم يعمل؛ فاليقظة التي لا تنتج علمًا تتحول إلى غضب، والعلم الذي لا ينتج عملًا يتحول إلى معلومات باردة.","المسلم لا يدافع عن الإسلام برفض العلم، بل بتعلمه، ولا يثبت صدق دينه بإلصاق فيزياء عصره، بل بأن يجمع بين معرفة الخالق وفهم خلقه، وبين أخلاق الوحي ودقة المختبر.","العدو الخارجي لا يعفينا من إصلاح الداخل. وما يحاك ضدنا لا ينجح إلا إذا وجد جهلًا أو ظلمًا أو فراغًا أو انقسامًا يستطيع أن يدخل منه.","الإسلام ليس اسمًا وشعارًا، ولا مجموعة محفوظات منفصلة، ولا طقوسًا تؤدى دون رؤية من الحياة. الإسلام استسلام واعٍ لله، ورؤية للوجود، وميزان للأخلاق، ومنهج يبني الإنسان والأسرة والمجتمع.","من يريد حماية الشباب لا يكتفي بمنعهم من الخطأ؛ يجب أن يعطيهم شيئًا عظيمًا يعيشون له: معرفة بالله، ورسالة أخلاقية، وعملًا نافعًا، ومشروعًا يشعرون أنهم شركاء فيه.","إذا لم يقدم البيت والمسجد والمدرسة للشاب جوابًا عاقلًا، ستقدم له المنصة جوابًا آخر."]);
  const AWARENESS_STORE = 'hasibat:image-awareness:0cab30d6538203bef04a';
  let awarenessStorage = null;
  function tipStorage() {
    if (awarenessStorage) return awarenessStorage;
    try {
      const storage = window.localStorage;
      const probe = AWARENESS_STORE+':probe';
      storage.setItem(probe,'ok');
      if (storage.getItem(probe)!=='ok') throw new Error('Storage is read-only');
      storage.removeItem(probe);
      awarenessStorage=storage;
      return storage;
    } catch(error) {
      throw new Error('لا يمكن حفظ ترتيب الرسائل التوعوية على هذا الجهاز. فعّل التخزين المحلي ثم أعد المحاولة.');
    }
  }
  function validTipState(state) {
    if (!state || !Array.isArray(state.order) || state.order.length!==AWARENESS_MESSAGES.length ||
        !Number.isInteger(state.index) || state.index<0 || state.index>AWARENESS_MESSAGES.length ||
        !Number.isInteger(state.last) || state.last< -1 || state.last>=AWARENESS_MESSAGES.length) return false;
    const unique=new Set(state.order);
    return unique.size===AWARENESS_MESSAGES.length &&
           state.order.every(n=>Number.isInteger(n) && n>=0 && n<AWARENESS_MESSAGES.length);
  }
  function shuffledTipIndices(previousLast) {
    const order=Array.from({length:AWARENESS_MESSAGES.length},(_,i)=>i);
    // Fisher–Yates shuffle: new random permutation each completed 53-image cycle.
    for(let i=order.length-1;i>0;i--){
      const j=Math.floor(Math.random()*(i+1));
      const tmp=order[i];order[i]=order[j];order[j]=tmp;
    }
    // Prevent the last message of a cycle repeating at the next cycle boundary.
    if (order[0]===previousLast && order.length>1) {
      const j=1+Math.floor(Math.random()*(order.length-1));
      const tmp=order[0];order[0]=order[j];order[j]=tmp;
    }
    return order;
  }
  function reserveImageAwareness() {
    const store=tipStorage();
    let state=null;
    try {state=JSON.parse(store.getItem(AWARENESS_STORE)||'null');}catch(error){}
    if(!validTipState(state)) state={order:shuffledTipIndices(-1),index:0,last:-1};
    if(state.index===AWARENESS_MESSAGES.length) {
      state={order:shuffledTipIndices(state.last),index:0,last:state.last};
    }
    const id=state.order[state.index];
    const next={order:state.order,index:state.index+1,last:id};
    return {
      id:id,
      text:AWARENESS_MESSAGES[id],
      // Only advance after PNG export succeeded. A failed render consumes nothing.
      commit:function() {
        try{store.setItem(AWARENESS_STORE,JSON.stringify(next));}
        catch(error){throw new Error('تعذّر حفظ ترتيب الرسائل، فلم يتم احتساب إنشاء الصورة.');}
      }
    };
  }
  // Respect user-authored paragraph breaks and fit long Arabic texts inside
  // the existing green and gold message container, expanding only its height.
  function wrapAwareness(ctx,text,maxWidth,fontSize) {
    ctx.save();ctx.font='700 '+fontSize+'px Tahoma, Arial, sans-serif';
    const lines=[];
    for(const paragraph of String(text).split(/\r?\n/)){
      const words=paragraph.trim().split(/\s+/).filter(Boolean);
      if(!words.length){lines.push('');continue;}
      let line='';
      for(const word of words){
        const attempt=line ? line+' '+word : word;
        if(line && ctx.measureText(attempt).width>maxWidth){lines.push(line);line=word;}
        else line=attempt;
      }
      if(line)lines.push(line);
    }
    ctx.restore();
    return lines;
  }

  function allVisibleKeys() {
    const extra = window.HasibatWorldCurrencies;
    if (extra && typeof extra.getVisibleKeys === 'function') {
      const keys = extra.getVisibleKeys();
      if (Array.isArray(keys) && keys.length && keys.length <= 16) return keys;
    }
    return coreRows;
  }
  function resultCode(key) {
    const extra = window.HasibatWorldCurrencies;
    return extra && typeof extra.getCode === 'function' ? extra.getCode(key) : (codes[key] || key.toUpperCase());
  }
  function basenameNow() {return 'Hasibat-AlLira-Results-' + new Date().toISOString().replace(/[:.]/g,'-') + '.png';}
  function appLogo() {
    return new Promise(resolve => {
      const image = new Image();
      image.onload=()=>resolve(image);
      image.onerror=()=>resolve(null);
      image.src='data:image/png;base64,';
    });
  }


  function inform(message, isError) {
    status.hidden = false;
    status.textContent = message;
    status.dataset.error = isError ? 'true' : 'false';
    const live=document.getElementById('sharePreviewFeedback');
    if(live){live.textContent=message;live.style.color=isError?'#ffd2bb':'#f6e1a2';}
  }
  window.onShareResultStatus = function (message, error) {
    inform(String(message || ''), !!error);
  };
  function timeLabel(date) {
    return new Intl.DateTimeFormat('ar-SY-u-nu-latn', {
      day:'2-digit', month:'2-digit', year:'numeric',
      hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false
    }).format(date);
  }
  function contextText(ctx, text, x, y, size, color, weight, align, maxWidth) {
    ctx.save();
    ctx.direction = align === 'left' ? 'ltr' : 'rtl';
    ctx.textAlign = align || 'right';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.font = (weight || 700) + ' ' + size + 'px Tahoma, Arial, sans-serif';
    if (maxWidth) ctx.fillText(String(text), x, y, maxWidth);
    else ctx.fillText(String(text), x, y);
    ctx.restore();
  }
  function rounded(ctx,x,y,w,h,r) {
    ctx.beginPath();
    if (typeof ctx.roundRect === 'function') ctx.roundRect(x,y,w,h,r);
    else {
      ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);
      ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);
      ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);
      ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
    }
  }
  function collectSnapshot() {
    const amount = normalizeNumber(amountInput.value);
    const selected = currencySelect.value;
    if (!resultCode(selected) || amount===null || !Number.isFinite(amount) || amount<0 || amount>1e15) {
      throw new Error('أدخل مبلغًا صحيحًا قبل مشاركة النتائج.');
    }
    // The same validated cached/live prices drive both the UI and the image.
    if (!model.rates || !validateRates(model.rates)) {
      throw new Error('لا توجد أسعار صرف موثقة محفوظة. حدّث الأسعار ثم حاول مشاركة الصورة.');
    }
    const results = allVisibleKeys().map(key => {
      const amountOut = calculate(amount, selected, key);
      if (amountOut===null || !Number.isFinite(amountOut)) {
        throw new Error('بعض نتائج التحويل غير متاحة الآن. حدّث الأسعار ثم حاول مجددًا.');
      }
      return {key, code:resultCode(key), title:labels[key] || resultCode(key), value:readableResult(amountOut,key).main, exact:(readableResult(amountOut,key).precise||readableResult(amountOut,key).main)};
    });
    const created = new Date(); // Only captured once; exact to the second.
    const checked = new Date(model.rates.checkedAt);
    if (Number.isNaN(checked.getTime())) throw new Error('تاريخ أسعار الصرف غير متاح.');
    return {
      amount, selected, inputLabel:labels[selected] || resultCode(selected), inputCode:resultCode(selected),
      createdAt:timeLabel(created), checkedAt:timeLabel(checked),
      stale:model.connection!=='online',
      results
    };
  }
  async function generatePng(snapshot,omitLogo=false) {
    const canvas = document.createElement('canvas');
    const W=1080;
    canvas.width=W;
    const measure=canvas.getContext('2d');
    if (!measure) throw new Error('تعذر إنشاء الصورة في هذا الجهاز.');
    if (!snapshot.awareness || !AWARENESS_MESSAGES.includes(snapshot.awareness.text))
      throw new Error('الرسالة التوعوية المحددة غير موجودة في القائمة المعتمدة.');
    const messageFontSize=24, messageLineHeight=34;
    const messageLines=wrapAwareness(measure,snapshot.awareness.text,794,messageFontSize);
    const messageBoxHeight=Math.max(90,57+messageLines.length*messageLineHeight);
    const H=1690+Math.max(0,snapshot.results.length-5)*156+Math.max(0,messageBoxHeight-90);
    canvas.height=H;
    const ctx=canvas.getContext('2d');
    if (!ctx) throw new Error('تعذر إنشاء الصورة في هذا الجهاز.');
    const bg=ctx.createLinearGradient(0,0,W,H);
    bg.addColorStop(0,'#071b15');bg.addColorStop(.55,'#123d2b');bg.addColorStop(1,'#06150f');
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    // Subtle decorative arcs, inset safe zone and a restrained metallic border.
    for (let i=0;i<5;i++) {
      ctx.beginPath();ctx.arc(1080,0,140+i*82,0,Math.PI*2);
      ctx.strokeStyle='rgba(237,202,120,'+(0.13-i*.019)+')';ctx.lineWidth=2;ctx.stroke();
    }
    rounded(ctx,38,35,1004,H-70,34);ctx.strokeStyle='#a78c55';ctx.lineWidth=2;ctx.stroke();
    rounded(ctx,54,51,972,H-102,28);ctx.strokeStyle='rgba(255,227,154,0.24)';ctx.lineWidth=1;ctx.stroke();
    // Monochrome brand ornament, created locally without network assets.
    ctx.beginPath();ctx.arc(540,136,44,0,Math.PI*2);
    ctx.fillStyle='#d9b86a';ctx.fill();
    contextText(ctx,'ل',540,138,48,'#0b2b1f',900,'center');
    // Use the actual original app icon. Keep the gold monogram as an offline fallback.
    const logo = omitLogo ? null : await appLogo();
    if (logo) {
      rounded(ctx,495,90,90,90,19);
      ctx.save();ctx.clip();ctx.drawImage(logo,495,90,90,90);ctx.restore();
    }
    contextText(ctx,'حاسبة الليرة السورية',540,218,49,'#fff8e6',900,'center');
    contextText(ctx,'نتائج تحويل العملات',540,273,26,'#e9d094',700,'center');
    ctx.fillStyle='#c8a65c';ctx.fillRect(120,311,840,2);
    rounded(ctx,100,345,880,159,20);
    const band=ctx.createLinearGradient(120,350,980,504);
    band.addColorStop(0,'#224a32');band.addColorStop(1,'#143527');
    ctx.fillStyle=band;ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#bd9e61';ctx.stroke();
    contextText(ctx,'المبلغ المدخل',940,385,27,'#f7e0a4',750,'right');
    contextText(ctx,snapshot.inputLabel+'  ·  '+snapshot.inputCode,940,454,28,'#fff7e8',700,'right');
    contextText(ctx,formatNumber(snapshot.amount,snapshot.selected),135,443,56,'#ffffff',900,'left',455);
    contextText(ctx,'القيم المحوّلة',940,552,30,'#ffe2a0',850,'right');
    let y=584;
    for (const r of snapshot.results) {
      const active=r.key===snapshot.selected;
      rounded(ctx,100,y,880,145,21);
      ctx.fillStyle=active?'#224d36':(y%2?'#123528':'#143c2c');ctx.fill();
      ctx.lineWidth=active?3:1.4;ctx.strokeStyle=active?'#efd38d':'#54755a';ctx.stroke();
      rounded(ctx,830,y+18,119,42,20);ctx.fillStyle='#463b22';ctx.fill();
      contextText(ctx,r.code,889,y+41,20,'#ffe4a1',800,'center');
      contextText(ctx,r.title,795,y+51,27,'#fffaf0',800,'right');
      contextText(ctx,r.value,135,y+101,42,'#ffffff',900,'left',575);
      if(r.exact!==r.value) contextText(ctx,'القيمة الدقيقة: '+r.exact,135,y+131,17,'#c9ddd2',600,'left',650);
      contextText(ctx,active?'العملة المختارة':'سعر التحويل الوسطي',942,y+108,19,'#e2eadd',650,'right');
      y+=156;
    }
    // Result rows end at y=1364; timestamps remain visually independent.
    ctx.fillStyle='#bf9d55';ctx.fillRect(110,y+18,860,2);
    contextText(ctx,'وقت إنشاء الصورة: '+snapshot.createdAt,947,y+48,23,'#fff4d8',750,'right');
    contextText(ctx,'آخر تحديث ناجح للأسعار: '+snapshot.checkedAt,947,y+88,19,'#cbdccc',650,'right');
    contextText(ctx,snapshot.stale?'أسعار محفوظة — قد تكون غير محدثة':'أسعار متاحة وقت إنشاء الصورة',947,y+126,20,snapshot.stale?'#ffd08a':'#cde9d3',750,'right');
    // Exact text chosen once per successful generation; no truncated or invented messages.
    rounded(ctx,101,y+153,879,messageBoxHeight,17);
    ctx.fillStyle='#15442e';ctx.fill();ctx.strokeStyle='#c7a662';ctx.lineWidth=1;ctx.stroke();
    contextText(ctx,'رسالة نافعة',941,y+179,19,'#e9c67c',800,'right');
    for(let i=0;i<messageLines.length;i++) {
      contextText(ctx,messageLines[i],940,y+153+62+i*messageLineHeight,
                  messageFontSize,'#ffffff',700,'right',799);
    }
    try { return canvas.toDataURL('image/png'); } catch(error) {
      if (!omitLogo && error && error.name === 'SecurityError') return generatePng(snapshot,true);
      throw error;
    }
  }
  function makeBlob(dataUrl) {
    const arr=dataUrl.split(',');
    const binary=atob(arr[1]);
    const bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
    return new Blob([bytes],{type:'image/png'});
  }
  function bridge() {
    return window.ResultShareHost && typeof window.ResultShareHost.saveResultsImage === 'function'
      ? window.ResultShareHost : null;
  }
  async function nativeSave(dataUrl, filename) {
    const api=bridge();
    if (api) {
      inform('جارٍ حفظ الصورة في معرض الصور…',false);
      api.saveResultsImage(dataUrl,filename);
      // The native bridge reports success/failure using onShareResultStatus.
      return;
    }
    // Browser only. Android WebView data: downloads are not a supported fallback.
    if (window.CurrencyHost) throw new Error('للحفظ المباشر يرجى تثبيت إصدار حاسبة الليرة الذي يدعم جسر حفظ الصور.');
    const blob=makeBlob(dataUrl),href=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=href;a.download=filename;
    a.style.display='none';document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(href),2000);
    inform('تم إرسال الصورة إلى تنزيلات المتصفح.',false);
  }
  async function nativeShare(dataUrl,filename) {
    const api=bridge();
    if(api && typeof api.shareResultsImage==='function') {
      inform('جارٍ فتح قائمة المشاركة…',false);
      api.shareResultsImage(dataUrl,filename);
      return;
    }
    const image=new File([makeBlob(dataUrl)],filename,{type:'image/png'});
    if (navigator.share && navigator.canShare && navigator.canShare({files:[image]})) {
      try {await navigator.share({files:[image],title:'نتائج حاسبة الليرة السورية'});inform('تم فتح قائمة المشاركة.',false);return;}
      catch (e) {if(e && e.name==='AbortError'){inform('تم إلغاء المشاركة.',false);return;}}
    }
    throw new Error('المشاركة المباشرة تتطلب تحديث التطبيق. يمكن حفظ PNG أولًا أو استخدام متصفح يدعم مشاركة الملفات.');
  }
  function showPreview(dataUrl,filename) {
    document.getElementById('shareResultsPreview')?.remove();
    const overlay=document.createElement('div');overlay.id='shareResultsPreview';
    Object.assign(overlay.style,{position:'fixed',inset:'0',zIndex:'2147483647',overflowY:'auto',background:'#071b15',padding:'18px 12px 32px',color:'#fff3d4',textAlign:'center',fontFamily:'Tahoma,Arial,sans-serif',boxSizing:'border-box'});
    const header=document.createElement('div');header.dir='rtl';header.style.margin='8px 0 16px';
    header.textContent='معاينة صورة نتائج التحويل — اختر الحفظ أو المشاركة';
    const img=document.createElement('img');img.src=dataUrl;img.alt='صورة نتائج حاسبة الليرة';
    Object.assign(img.style,{width:'100%',maxWidth:'540px',height:'auto',borderRadius:'16px',border:'1px solid #e8c473'});
    const buttons=document.createElement('div');Object.assign(buttons.style,{display:'flex',gap:'10px',justifyContent:'center',marginTop:'16px',flexWrap:'wrap'});
    function button(label,bg,color){const b=document.createElement('button');b.type='button';b.textContent=label;Object.assign(b.style,{background:bg,color,padding:'13px 18px',borderRadius:'12px',border:'1px solid #e5c477',font:'inherit'});return b;}
    const save=button('حفظ PNG','#e5c477','#10291e');
    const share=button('مشاركة','#e5c477','#10291e');
    const close=button('إغلاق','#173d2b','#fff');
    save.addEventListener('click',()=>nativeSave(dataUrl,filename).catch(e=>inform(e.message,true)));
    share.addEventListener('click',()=>nativeShare(dataUrl,filename).catch(e=>inform(e.message,true)));
    close.onclick=()=>overlay.remove();
    const feedback=document.createElement('p');feedback.id='sharePreviewFeedback';
    feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');
    Object.assign(feedback.style,{fontSize:'14px',color:'#f6e1a2',margin:'14px 5px'});
    feedback.textContent='الصورة جاهزة؛ اضغط حفظ أو مشاركة.';
    buttons.append(save,share,close);overlay.append(header,img,buttons,feedback);document.body.appendChild(overlay);
  }
  window.HasibatShareTools=Object.freeze({showPreview,reserveImageAwareness,timeLabel,contextText,rounded,appLogo,inform});
  let busy=false;
  shareButton.addEventListener('click',async function(){
    if (busy) return;
    busy=true;shareButton.disabled=true;
    try {
      const snapshot=collectSnapshot();
      const nextAwareness=reserveImageAwareness();
      snapshot.awareness={id:nextAwareness.id,text:nextAwareness.text};
      const png=await generatePng(snapshot);
      const filename=basenameNow();
      // Persist before preview: save/share reuse this very same PNG and message.
      nextAwareness.commit();
      showPreview(png,filename);
      inform('الصورة جاهزة؛ اضغط حفظ PNG أو مشاركة.',false);
    }catch(error){inform((error&&error.message)||'تعذر إنشاء صورة النتائج.',true);}
    finally{busy=false;shareButton.disabled=false;}
  });
})();
